const columns={patient_id:['Patient ID','Potilastunnus'],sex:['Sex','Sukupuoli'],birth_year:['Birth year','Syntymävuosi'],home_area:['Home area','Asuinalue'],culture_id:['Sample ID','Näytetunnus'],age_years:['Age at sampling','Ikä näytteenotossa'],sample_date:['Sample date','Näytteenottopäivä'],iso_year:['ISO year','ISO-vuosi'],iso_week:['ISO week','ISO-viikko'],ward_code:['Location code','Hoitopaikan koodi'],ward_fi:['Location · Finnish','Hoitopaikka · suomi'],ward_en:['Location · English','Hoitopaikka · englanti'],ward_type:['Care setting','Hoitomuoto'],institution:['Organisation type','Organisaatiotyyppi'],admission_date:['Admission date','Sisäänottopäivä'],specimen:['Sample type','Näytetyyppi'],specimen_fi:['Sample type · Finnish','Näytetyyppi · suomi'],result:['Laboratory result','Laboratoriotulos'],n_isolates:['Organisms found','Löydettyjen mikrobien määrä'],isolate_id:['Finding ID','Löydöstunnus'],isolate_no:['Finding number','Löydöksen numero'],organism:['Organism','Mikrobi'],quantity:['Growth amount','Kasvun määrä'],esbl:['ESBL flag','ESBL-merkintä'],mrsa:['MRSA flag','MRSA-merkintä'],vre:['VRE flag','VRE-merkintä'],cpe:['CPE flag','CPE-merkintä'],antibiotic:['Antibiotic','Antibiootti'],antibiotic_code:['Antibiotic code','Antibioottikoodi'],antibiotic_fi:['Antibiotic · Finnish','Antibiootti · suomi'],guideline:['Interpretation standard','Tulkintaohje'],class:['Antibiotic class','Antibioottiryhmä'],reported_for:['Reported sample types','Raportoitavat näytetyypit']};
