function value(v,k){if(v==='')return '—';if(['esbl','mrsa','vre','cpe'].includes(k))return v==='1'?t('Present','Todettu'):t('Not flagged','Ei merkintää');const map={urine:['Urine','Virtsa'],blood:['Blood','Veri'],wound:['Wound','Haava'],positive:['Positive','Positiivinen'],negative:['Negative','Negatiivinen'],mixed_growth:['Mixed growth','Sekakasvu'],in:['Inpatient','Osastohoito'],out:['Outpatient','Avohoito'],hospital:['Hospital','Sairaala'],primary_care:['Primary care','Perusterveydenhuolto'],F:['Female','Nainen'],M:['Male','Mies']};if(k==='result'&&v==='R')return t('R · Resistant','R · Resistentti');if(k==='result'&&v==='S')return t('S · Susceptible','S · Herkkä');return map[v]?t(...map[v]):v;}
const title=()=>t(...navDefs.find(n=>n[0]===view).slice(2)),card=(name,body,extra='')=>`<section class="card"><div class="card-head"><h2>${name}</h2>${extra}</div>${body}</section>`,notice=(text,amber=false)=>`<div class="notice ${amber?'amber':''}">${text}</div>`;
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3500);}
async function raw(name){if(!cache[name]){const paths=name==='susceptibility'?['datasets/susceptibility.part1.json','datasets/susceptibility.part2.json']:['datasets/'+name+'.json'];const parts=await Promise.all(paths.map(async path=>{const r=await fetch(path);if(!r.ok)throw Error(t('Data unavailable','Tiedot eivät ole saatavilla'));return r.json();}));const a={columns:parts[0].columns,rows:parts.flatMap(p=>p.rows)};cache[name]=a.rows.map(r=>Object.fromEntries(a.columns.map((c,i)=>[c,r[i]])));}return cache[name];}
function saveBlob(name,content,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function csv(name,rows){if(!rows.length)return toast(t('No records to export.','Ei vietäviä tietueita.'));const cols=Object.keys(rows[0]);saveBlob(name+'.csv',[cols,...rows.map(r=>cols.map(k=>r[k]))].map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n'),'text/csv;charset=utf-8');}
function dataTable(rows,limit=Infinity){if(!rows.length)return '<div class="empty">'+t('No matching records.','Ei vastaavia tietueita.')+'</div>';return `<div class="table-wrap raw-table"><table><thead><tr>${Object.keys(rows[0]).map(k=>`<th title="${esc(k)}">${esc(label(k))}<small>${esc(k)}</small></th>`).join('')}</tr></thead><tbody>${rows.slice(0,limit).map(r=>`<tr>${Object.entries(r).map(([k,v])=>`<td>${k==='patient_id'?`<button class="plain patient-link" data-pid="${esc(v)}">${esc(v)}</button>`:esc(value(v,k))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function bindPatientLinks(){$$('.patient-link').forEach(b=>b.onclick=()=>{pid=b.dataset.pid;go('patients');});}
function go(v){view=v;epoch++;render();window.scrollTo({top:0,behavior:'smooth'});}
function select(id,caption,options){return `<label>${caption}<select id="${id}">${options.map(([v,l])=>`<option value="${v}" ${String(f[id])===String(v)?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`;}
function cohortControls(){const all=t('All','Kaikki');return `<section class="card"><div class="pad"><div class="filters">${select('ward',t('Care location','Hoitopaikka'),[['ALL',all],...data.wards.map(w=>[w.ward_code,lang==='fi'?w.ward_fi:w.ward_en])])}${select('organism',t('Organism','Mikrobi'),[['ALL',all],...data.organisms.map((o,i)=>[i,o])])}${select('specimen',t('Sample type','Näytetyyppi'),[['ALL',all],...['urine','blood','wound'].map(v=>[v,value(v,'specimen')])])}${select('sex',t('Sex','Sukupuoli'),[['ALL',all],['F',t('Female','Nainen')],['M',t('Male','Mies')]])}${select('age',t('Age group','Ikäryhmä'),[['ALL',all],['65',t('65 and older','65 vuotta täyttäneet')],['18',t('Under 18','Alle 18 vuotta')]])}</div><details class="advanced"><summary>${t('More filters','Lisää suodattimia')}</summary><div class="filters">${select('institution',t('Organisation','Organisaatio'),[['ALL',all],['hospital',t('Hospital','Sairaala')],['primary_care',t('Primary care','Perusterveydenhuolto')]])}${select('care',t('Care setting','Hoitomuoto'),[['ALL',all],['in',t('Inpatient','Osastohoito')],['out',t('Outpatient','Avohoito')]])}${select('area',t('Home area','Asuinalue'),[['ALL',all],...[...new Set(data.rows.map(r=>r[16]))].sort().map(v=>[v,v])])}${select('onset',t('Admission timing','Sisäänoton ajoitus'),[['ALL',all],['late',t('Day 3 or later','Hoitopäivä 3 tai myöhemmin')],['early',t('Days 1–2','Hoitopäivät 1–2')]])}${select('phenotype',t('Resistance marker','Resistenssimerkki'),[['ALL',all],...['esbl','mrsa','vre','cpe'].map(v=>[v,v.toUpperCase()])])}</div></details></div><div class="date-row"><div><strong>${t('Reporting date','Raportointipäivä')}</strong> <input type="date" id="date" value="${f.date}" min="${data.meta.start}" max="${data.meta.end}" aria-label="${t('Reporting date','Raportointipäivä')}"></div><div class="toolbar"><span>${t('Historical replay · not a live hospital feed','Historiatoisto · ei reaaliaikainen sairaalayhteys')}</span><button id="replay">${replay?'Ⅱ': '▶'} ${t('Replay','Toista')}</button><button id="latest">${t('Latest','Uusin')}</button><button id="reset">${t('Reset','Nollaa')}</button></div></div></section>`;}
function shell(){const navigation=navDefs.filter(n=>role!=='patient'||['patients','directory','chat','methods','overview'].includes(n[0]));const study=['overview','signals','growth','comparisons','forecasts'].includes(view);$('#app').innerHTML=`<aside class="sidebar"><a href="#" id="home"><img class="logo" src="logo.svg" alt="MicrobeLog"></a><div class="nav-label">${t('Laboratory workspace','Laboratorion työtila')}</div><nav>${navigation.map(n=>`<button class="nav ${view===n[0]?'active':''}" data-view="${n[0]}"><i>${n[1]}</i>${t(...n.slice(2))}</button>`).join('')}</nav><div class="side-foot"><span class="status-dot"></span>${t('Synthetic challenge dataset','Synteettinen kilpailuaineisto')}<br>Tyks × Mylab · JunctionX Turku<a href="source/">${t('Source code & documentation','Lähdekoodi ja dokumentaatio')} ↗</a><button class="plain" id="install">${t('Install on your phone','Asenna puhelimeen')} ↗</button></div></aside><div class="layout"><header class="topbar"><div class="toolbar"><button class="menu-button plain" id="menu" aria-label="${t('Open menu','Avaa valikko')}">☰</button><div class="crumb">MicrobeLog &nbsp;/&nbsp; <b>${title()}</b></div></div><div class="top-controls"><span class="demo-chip">${t('SYNTHETIC DEMO','SYNTEETTINEN DEMO')}</span><select id="role" aria-label="${t('Workspace view','Työtilanäkymä')}"><option value="clinical" ${role==='clinical'?'selected':''}>${t('Hospital staff','Sairaalan henkilöstö')}</option><option value="research" ${role==='research'?'selected':''}>${t('Research & development','Tutkimus ja kehitys')}</option><option value="patient" ${role==='patient'?'selected':''}>${t('Patient view','Potilasnäkymä')}</option></select><select id="lang" aria-label="Language / Kieli"><option value="en" ${lang==='en'?'selected':''}>English</option><option value="fi" ${lang==='fi'?'selected':''}>Suomi</option></select></div></header><main><div class="heading"><div><div class="eyebrow">${role==='patient'?t('Understand your laboratory results','Ymmärrä laboratoriotuloksesi'):t('Microbiology · local evidence','Mikrobiologia · paikallinen tieto')}</div><h1>${title()}</h1><p>${study?t('The previous four weeks, with a rolling annual comparison.','Edelliset neljä viikkoa ja liukuva vuosivertailu.'):t('Connected records. Clear explanations. Traceable results.','Yhdistetyt tiedot. Selkeät selitykset. Jäljitettävät tulokset.')}</p></div>${study?`<button id="export" class="primary">↓ ${t('Export statistics','Vie tilastot')}</button>`:''}</div>${study?cohortControls():''}<div id="content"></div><footer><span>MicrobeLog · ${t('Research prototype, not a treatment recommendation','Tutkimusprototyyppi, ei hoitosuositus')}</span><span>${t('Data through','Aineisto päättyy')} ${data.meta.end} · <button class="plain" id="refresh">${t('Check for updates','Tarkista päivitykset')}</button> <span id="sync">${lastSync}</span></span></footer></main></div><nav class="mobile-nav">${(role==='patient'?['patients','overview','chat','methods']:['overview','patients','images','chat','explorer']).map(k=>{const n=navDefs.find(n=>n[0]===k);return `<button data-view="${k}" class="${view===k?'active':''}"><i>${n[1]}</i>${t(...n.slice(2))}</button>`;}).join('')}</nav>`;
$$('[data-view]').forEach(b=>b.onclick=()=>go(b.dataset.view));$('#home').onclick=e=>{e.preventDefault();go('overview');};$('#lang').onchange=e=>{lang=e.target.value;document.documentElement.lang=lang;localStorage.setItem('ml-lang',lang);render();};$('#role').onchange=e=>{role=e.target.value;go(role==='patient'?'patients':role==='research'?'explorer':'overview');};$('#menu').onclick=()=>$('.sidebar').classList.toggle('open');$('#install').onclick=installHelp;$('#refresh').onclick=()=>refreshData(true);if(study){Object.keys(f).forEach(k=>{const el=$('#'+k);if(el)el.onchange=()=>{if(k==='date'&&(!el.value||el.value<data.meta.start||el.value>data.meta.end)){el.value=f.date;return;}f[k]=el.value;render();};});$('#export').onclick=exportReport;$('#latest').onclick=()=>{stopReplay();f.date=data.meta.end;render();};$('#reset').onclick=()=>{Object.assign(f,{ward:'PHC-S',organism:String(data.organisms.indexOf('Escherichia coli')),specimen:'urine',sex:'ALL',age:'ALL',date:data.meta.end,institution:'ALL',care:'ALL',area:'ALL',onset:'ALL',phenotype:'ALL'});render();};$('#replay').onclick=()=>{if(replay){stopReplay();render();return;}if(f.date===data.meta.end)f.date=AEI.shift(data.meta.end,-84);replay=setInterval(()=>{f.date=AEI.shift(f.date,7);if(f.date>=data.meta.end){f.date=data.meta.end;stopReplay();}render();},1800);render();};}}
function stopReplay(){clearInterval(replay);replay=null;}
async function render(){if(!data)return;const n=++epoch;shell();report=AEI.compute(data,f);const handlers={comparisons:comparisons,forecasts:forecasts,directory:directory,overview:overview,signals:signals,patients:patients,growth:growth,explorer:explorer,images:images,research:research,chat:chat,methods:methods};try{await handlers[view](n);}catch(e){if(n===epoch)$('#content').innerHTML=notice(esc(e.message),true);}}
const rateBlock=c=>c.n>=30?`<div class="result-pair"><span class="r-rate">${percent(c.rate)} R</span><span class="s-rate">${percent(1-c.rate)} S</span></div><div class="tiny-bar"><i style="width:${100*c.rate}%"></i></div><small>R ${c.r} · S ${c.s} · n = ${c.n}</small>`:`<span class="tag">${t('Too few results','Liian vähän tuloksia')}</span><small>n = ${c.n} / 30 · R ${c.r} · S ${c.s}</small>`;
function stat(name,n,caption){return `<div class="stat"><div class="caption">${name}</div><strong>${num(n)}</strong><small>${caption}</small></div>`;}
const statusName=a=>a.status==='signal'?t('Review signal','Tarkistussignaali'):a.status==='watch'?t('Watch','Seurattava'):a.status==='limited'?t('Limited data','Vähän tietoa'):t('No signal','Ei signaalia'),statusTag=a=>`<span class="tag ${a.status==='signal'?'red':a.status==='watch'?'amber':''}">${statusName(a)}</span>`;
function antibioticTable(){return `<div class="table-wrap"><table><thead><tr><th>${t('ANTIBIOTIC','ANTIBIOOTTI')}</th><th>${t('PREVIOUS 4 WEEKS','EDELLISET 4 VIIKKOA')}</th><th>${t('ROLLING YEAR','LIUKUVA VUOSI')}</th><th>${t('CHANGE','MUUTOS')}</th></tr></thead><tbody>${report.metrics.map(a=>`<tr class="click-row" tabindex="0" data-code="${a.antibiotic_code}"><td><b>${esc(lang==='fi'?a.antibiotic_fi:a.antibiotic)}</b><small>${a.antibiotic_code}${a.antibiotic_code==='FOX'?' · '+t('MRSA screen, not a treatment ranking','MRSA-seulonta, ei hoitojärjestys'):''}</small></td><td>${rateBlock(a.now)}</td><td>${rateBlock(a.year)}</td><td>${statusTag(a)}<small>${a.now.n>=30&&a.baseline.n>=30?(a.delta>=0?'+':'')+a.delta.toFixed(1)+' pp':''}</small></td></tr>`).join('')||`<tr><td colspan="4">${t('No tests match these filters.','Ei suodattimia vastaavia tutkimuksia.')}</td></tr>`}</tbody></table></div><div class="table-foot">${t('R = resistant · S = susceptible. Percentages require at least 30 tested first isolates for each antibiotic. Select a row to inspect the calculation.','R = resistentti · S = herkkä. Prosentit edellyttävät vähintään 30 tutkittua ensisolaattia antibioottia kohden. Avaa laskelma valitsemalla rivi.')}</div>`;}
function bindEvidence(){$$('[data-code]').forEach(b=>{b.onclick=()=>evidence(b.dataset.code);b.onkeydown=e=>{if(e.key==='Enter')evidence(b.dataset.code);};});}
function overview(){const sig=report.metrics.filter(a=>['watch','signal'].includes(a.status));$('#content').innerHTML=`<div class="stats">${stat(t('First isolates · 4 weeks','Ensisolaatit · 4 viikkoa'),report.recent.length,t('Repeat findings removed','Toistuvat löydökset poistettu'))}${stat(t('First isolates · annual','Ensisolaatit · vuosi'),report.annual.length,t('365 days ending on the reporting date','365 päivää raportointipäivään asti'))}${stat(t('Reportable antibiotics','Raportoitavat antibiootit'),report.metrics.filter(a=>a.now.n>=30).length,t('Each with at least 30 tested isolates','Jokaisella vähintään 30 tutkittua isolaattia'))}${stat(t('Resistance changes','Resistenssin muutokset'),sig.length,t('Exploratory watch and review items','Alustavat seuranta- ja tarkistuskohteet'))}</div>${notice(t('One first isolate per patient, species, sample type and reporting period. Missing antibiotic tests are excluded. Recent and annual periods are deduplicated separately.','Yksi ensisolaatti potilasta, lajia, näytetyyppiä ja raportointijaksoa kohti. Puuttuvat antibioottitulokset jätetään pois. Lyhyt ja vuosijakso käsitellään erikseen.'))}<div class="grid"><div>${card(t('Antibiotic resistance & susceptibility','Antibioottiresistenssi ja herkkyys'),antibioticTable())}${trendCard()}</div><div>${card(t('Report at a glance','Raportin yhteenveto'),`<div class="pad"><p>${sig.length?t('A resistance increase deserves a closer look.','Resistenssin lisääntyminen vaatii tarkempaa tarkastelua.'):t('No increase meets the demo review or watch rules in this cohort.','Tässä ryhmässä mikään kasvu ei täytä demon tarkistus- tai seurantasääntöä.')}</p><p class="sub">${t('A signal is a prompt to review the evidence, not a confirmed outbreak.','Signaali kehottaa tarkistamaan tiedot. Se ei vahvista epidemiaa.')}</p><button data-go="signals">${t('Review changes','Tarkista muutokset')} →</button></div>`)}${sexComparison()}${card(t('Understand the result','Ymmärrä tulos'),`<div class="pad"><p>${t('Susceptible (S): the organism is reported susceptible to this antibiotic. Resistant (R): the test reports resistance. These laboratory results do not by themselves select treatment.','Herkkä (S): mikrobi on testin mukaan herkkä antibiootille. Resistentti (R): testissä todetaan resistenssi. Laboratoriotulos ei yksin ratkaise hoitoa.')}</p><button data-go="chat">${t('Ask in everyday language','Kysy arkikielellä')} →</button></div>`)}</div></div>`;bindEvidence();bindGo();bindTrend();}
function bindGo(){$$('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));}
function sexComparison(){const base={...f,organism:String(data.organisms.indexOf('Escherichia coli')),specimen:'urine',sex:'ALL'},code='AMP',comparisons=['F','M'].map(sex=>({sex,...AEI.counts(AEI.cohort(data,{...base,sex},AEI.shift(f.date,-364),f.date),code)}));return card(t('Urinary E. coli · women & men','Virtsan E. coli · naiset ja miehet'),`<div class="pad"><div class="sub">${t('Annual ampicillin resistance · other filters retained','Vuosijakson ampisilliiniresistenssi · muut suodattimet säilyvät')}</div>${comparisons.map(c=>`<div style="margin-top:16px"><b>${value(c.sex,'sex')}</b> ${c.n>=30?`<span class="r-rate">${percent(c.rate)} R</span>`:'—'}<div class="sub">R ${c.r} / n ${c.n}${c.n<30?' · '+t('Below reporting minimum','Alle raportointirajan'):''}</div></div>`).join('')}<p class="sub">${t('The README notes sex differences. The size and direction depend on the selected cohort; no causal conclusion is implied.','README mainitsee sukupuolierot. Eron suuruus ja suunta riippuvat ryhmästä; syy-yhteyttä ei päätellä.')}</p></div>`);}
let trendCode='AMP';
function trendCard(){if(!report.metrics.some(a=>a.antibiotic_code===trendCode))trendCode=report.metrics[0]?.antibiotic_code||'AMP';return card(t('Resistance over time','Resistenssi ajan kuluessa'),'<div class="chart" id="trend-chart"></div><div class="legend"><span>'+t('Rolling 28-day resistance','Liukuva 28 päivän resistenssi')+'</span></div>',`<select id="trend-code" aria-label="${t('Antibiotic','Antibiootti')}">${report.metrics.map(a=>`<option value="${a.antibiotic_code}" ${trendCode===a.antibiotic_code?'selected':''}>${esc(lang==='fi'?a.antibiotic_fi:a.antibiotic)}</option>`).join('')}</select>`);}
function bindTrend(){if(!$('#trend-chart'))return;const draw=()=>{const ss=AEI.trend(data,f,trendCode),x=i=>44+i*49,y=p=>180-p*150;let path='',continuing=false;ss.forEach((s,i)=>{if(s.n<30){continuing=false;return;}path+=(continuing?' L':' M')+x(i)+','+y(s.rate);continuing=true;});$('#trend-chart').innerHTML=`<svg viewBox="0 0 610 220" role="img" aria-label="${t('Resistance trend. Gaps mean fewer than 30 isolates.','Resistenssitrendi. Katkos tarkoittaa alle 30 isolaattia.')}">${[0,.25,.5,.75,1].map(p=>`<line x1="44" x2="590" y1="${y(p)}" y2="${y(p)}" stroke="#e2e9ed"/><text x="34" y="${y(p)+3}" text-anchor="end" fill="#718794" font-size="9">${p*100}%</text>`).join('')}<path d="${path}" fill="none" stroke="#b75a63" stroke-width="2.5"/>${ss.map((s,i)=>`<circle cx="${x(i)}" cy="${s.n>=30?y(s.rate):188}" r="3" fill="${s.n>=30?'#b75a63':'#bbc9d1'}"><title>${s.date}: ${s.n>=30?percent(s.rate):t('withheld','ei raportoida')}, n=${s.n}</title></circle>${i%3===0||i===11?`<text x="${x(i)}" y="207" text-anchor="middle" font-size="9" fill="#718794">${s.date.slice(5)}</text>`:''}`).join('')}</svg>`;};draw();$('#trend-code').onchange=e=>{trendCode=e.target.value;draw();};}
function evidence(code){const a=report.metrics.find(a=>a.antibiotic_code===code);const ci=c=>c.n>=30?AEI.wilson(c.r,c.n).map(percent).join(' – '):t('Withheld','Ei raportoida');$('#modal').innerHTML=`<div class="dialog-head"><h2>${esc(lang==='fi'?a.antibiotic_fi:a.antibiotic)} · ${code}</h2><button id="close">×</button></div><div class="pad">${notice(t('Resistance = R ÷ (R + S) × 100. Only tested first isolates enter the denominator.','Resistenssi = R ÷ (R + S) × 100. Nimittäjässä ovat vain tutkitut ensisolaatit.'))}<div class="grid equal"><div><h3>${t('Previous four weeks','Edelliset neljä viikkoa')}</h3>${rateBlock(a.now)}<p class="sub">95% CI · ${ci(a.now)}</p></div><div><h3>${t('Rolling year','Liukuva vuosi')}</h3>${rateBlock(a.year)}<p class="sub">95% CI · ${ci(a.year)}</p></div></div><hr><p>${t('Historical comparison','Historiavertailu')}: R ${a.baseline.r} / ${a.baseline.n} · ${a.baseline.n>=30?percent(a.baseline.rate):'—'}</p><p>${t('Baseline: the 365 days immediately before the recent 28-day window.','Vertailujakso: 365 päivää juuri ennen viimeisintä 28 päivän jaksoa.')}</p><p>${statusTag(a)} ${a.now.n>=30&&a.baseline.n>=30?'Δ '+a.delta.toFixed(2)+' pp · p '+a.p.toFixed(5)+' · q '+a.q.toFixed(5):t('At least 30 tested isolates are needed in both comparison periods.','Molemmissa vertailujaksoissa tarvitaan vähintään 30 tutkittua isolaattia.')}</p><p class="sub">${t('Watch: ≥10 percentage-point increase. Review signal: also one-sided Fisher exact test with Benjamini–Hochberg q ≤ 0.05 across eligible antibiotics in this view. Exploratory rules, not clinical validation.','Seuranta: kasvu vähintään 10 prosenttiyksikköä. Tarkistussignaali: lisäksi yksisuuntainen Fisherin tarkka testi ja Benjamini–Hochberg q ≤ 0,05 tämän näkymän kelpoisille antibiooteille. Alustavat säännöt, ei kliinistä validointia.')}</p></div>`;$('#modal').showModal();$('#close').onclick=()=>$('#modal').close();}
function exportReport(){csv('MicrobeLog-'+f.date,report.metrics.map(a=>({as_of:f.date,ward:f.ward,organism:f.organism==='ALL'?'ALL':data.organisms[+f.organism],specimen:f.specimen,sex:f.sex,age:f.age,institution:f.institution,care:f.care,home_area:f.area,onset:f.onset,phenotype:f.phenotype,antibiotic:a.antibiotic_code,current_start:AEI.shift(f.date,-27),current_n:a.now.n,current_R:a.now.r,current_S:a.now.s,resistance_pct:a.now.n>=30?100*a.now.rate:'',susceptibility_pct:a.now.n>=30?100*(1-a.now.rate):'',annual_n:a.year.n,annual_R:a.year.r,annual_S:a.year.s,annual_resistance_pct:a.year.n>=30?100*a.year.rate:'',annual_susceptibility_pct:a.year.n>=30?100*(1-a.year.rate):'',baseline_n:a.baseline.n,baseline_R:a.baseline.r,change_pp:a.now.n>=30&&a.baseline.n>=30?a.delta:'',fisher_p:a.now.n>=30&&a.baseline.n>=30?a.p:'',adjusted_q:a.now.n>=30&&a.baseline.n>=30?a.q:'',status:a.status})));}
function signals(){const rows=report.metrics.filter(a=>['signal','watch'].includes(a.status));$('#content').innerHTML=notice(t('Review changes in the tested population, data completeness and interpretation standards before investigating a possible cluster. These are exploratory signals, not outbreak predictions.','Tarkista tutkitun väestön muutokset, aineiston kattavuus ja tulkintaohjeet ennen mahdollisen ryppään tutkimista. Signaalit ovat alustavia, eivät epidemiaennusteita.'))+card(t('Review queue','Tarkistusjono'),rows.length?`<div class="table-wrap"><table><thead><tr><th>${t('Antibiotic','Antibiootti')}</th><th>${t('Recent resistance','Viimeisin resistenssi')}</th><th>${t('Baseline','Vertailutaso')}</th><th>Δ pp / q</th></tr></thead><tbody>${rows.map(a=>`<tr class="click-row" data-code="${a.antibiotic_code}" tabindex="0"><td>${esc(lang==='fi'?a.antibiotic_fi:a.antibiotic)}<br>${statusTag(a)}</td><td>${percent(a.now.rate)}<small>R ${a.now.r}/${a.now.n}</small></td><td>${percent(a.baseline.rate)}<small>R ${a.baseline.r}/${a.baseline.n}</small></td><td>+${a.delta.toFixed(1)}<small>q = ${a.q.toFixed(5)}</small></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">${t('No watch or review items for this selection. Low sample sizes can prevent signals from being assessed.','Ei seuranta- tai tarkistuskohteita tällä valinnalla. Pieni otos voi estää signaalien arvioinnin.')}</div>`);bindEvidence();}
async function explorer(n){const rows=await raw(tableName);if(n!==epoch)return;const cols=Object.keys(rows[0]),filtered=rows.filter(r=>!search||(searchField==='ALL'?Object.values(r):[r[searchField]]).some(v=>String(v).toLowerCase().includes(search.toLowerCase())));page=Math.min(page,Math.max(0,Math.ceil(filtered.length/40)-1));$('#content').innerHTML=notice(t('Browse every original field. This workspace searches the full source table independently of the ward report filters. Technical field names appear below friendly labels for traceability.','Selaa kaikkia alkuperäisiä kenttiä. Tämä näkymä hakee koko lähdetaulusta osastoraportin suodattimista riippumatta. Tekniset kenttänimet näkyvät selkokielisten nimien alla.'))+`<div class="screen-tabs">${Object.entries(tableLabels).map(([k,l])=>`<button data-table="${k}" class="${k===tableName?'active':''}">${t(...l)}</button>`).join('')}</div>`+card(t(...tableLabels[tableName]),`<form class="pad toolbar" id="search-form"><label>${t('Search field','Hakukenttä')} <select id="search-field"><option value="ALL">${t('All fields','Kaikki kentät')}</option>${cols.map(k=>`<option value="${k}" ${searchField===k?'selected':''}>${label(k)}</option>`)}</select></label><input id="search" class="grow" value="${esc(search)}" placeholder="${t('Search an ID, date, organism or result…','Hae tunnusta, päivää, mikrobia tai tulosta…')}" aria-label="${t('Search records','Hae tietueita')}"><button>${t('Search','Hae')}</button><button type="button" id="export-matches">↓ ${t('Export matches','Vie hakutulokset')}</button></form><div class="table-foot">${num(filtered.length)} / ${num(rows.length)} ${t('records','tietuetta')} · ${cols.length} ${t('fields','kenttää')} · ${t('Page','Sivu')} ${page+1} / ${Math.max(1,Math.ceil(filtered.length/40))}</div>${dataTable(filtered.slice(page*40,page*40+40))}<div class="pad toolbar"><button id="prev" ${!page?'disabled':''}>← ${t('Previous','Edellinen')}</button><button id="next" ${(page+1)*40>=filtered.length?'disabled':''}>${t('Next','Seuraava')} →</button><a href="datasets/${tableName}.csv" download>${t('Download complete table','Lataa koko taulu')} (CSV)</a></div>`);$$('[data-table]').forEach(b=>b.onclick=()=>{tableName=b.dataset.table;page=0;search='';searchField='ALL';render();});$('#search-form').onsubmit=e=>{e.preventDefault();search=$('#search').value;searchField=$('#search-field').value;page=0;render();};$('#prev').onclick=()=>{page--;render();};$('#next').onclick=()=>{page++;render();};$('#export-matches').onclick=()=>csv('MicrobeLog-'+tableName+'-filtered',filtered);bindPatientLinks();}
async function patients(n){const [ps,cs,is,ss]=await Promise.all(['patients','cultures','isolates','susceptibility'].map(raw));if(n!==epoch)return;const p=ps.find(p=>p.patient_id===pid),cultures=cs.filter(c=>c.patient_id===pid).sort((a,b)=>b.sample_date.localeCompare(a.sample_date)),ids=new Set(cultures.map(c=>c.culture_id)),isolates=is.filter(i=>ids.has(i.culture_id)),tests=ss.filter(s=>ids.has(s.culture_id));$('#content').innerHTML=notice(t('All patients and records are invented. Workspace selection changes presentation only; it is not patient authentication or access control.','Kaikki potilaat ja tiedot ovat keksittyjä. Näkymän valinta muuttaa vain esitystapaa; se ei ole potilaan tunnistautuminen tai käyttöoikeusrajaus.'))+card(t('Find a patient record','Etsi potilastiedot'),`<form class="pad toolbar" id="patient-form"><label>${t('Synthetic patient ID','Synteettinen potilastunnus')} <input id="pid" value="${esc(pid)}" placeholder="P000001" pattern="P[0-9]{6}" required></label><button class="primary">${t('Open record','Avaa tiedot')}</button>${p?`<button type="button" id="patient-download">↓ ${t('Download complete record','Lataa kaikki tiedot')} (JSON)</button>`:''}</form>`)+(p?card(t('Patient summary','Potilaan yhteenveto'),`<div class="pad patient-summary"><dl class="kv">${Object.entries(p).map(([k,v])=>`<div><dt>${label(k)}</dt><dd>${esc(value(v,k))}</dd></div>`).join('')}</dl><div class="toolbar"><span class="tag">${cultures.length} ${t('samples','näytettä')}</span><span class="tag">${isolates.length} ${t('organism findings','mikrobilöydöstä')}</span><span class="tag">${tests.length} ${t('antibiotic results','herkkyystulosta')}</span></div></div>`)+card(t('What the findings can tell you','Mitä löydökset voivat kertoa'),`<div class="pad"><p>${t('A positive culture means an organism grew in the sample. It does not on its own establish an infection or its severity. Your healthcare team interprets it with symptoms and other tests.','Positiivinen viljely tarkoittaa, että näytteessä kasvoi mikrobi. Se ei yksin vahvista infektiota tai sen vakavuutta. Hoitohenkilöstö tulkitsee tulosta oireiden ja muiden tutkimusten kanssa.')}</p><p>${t('S means susceptible and R means resistant in the recorded antibiotic test. A missing test is unknown, not susceptible.','S tarkoittaa herkkää ja R resistenttiä kirjatussa antibioottitestissä. Puuttuva tulos tarkoittaa, ettei tietoa ole – ei herkkyyttä.')}</p><p class="sub">${t('Condition predictions are not calculated: symptoms, diagnoses, medication and outcome labels are absent from this dataset. No patient disease probability can be validated from these files.','Sairausennusteita ei lasketa: oireet, diagnoosit, lääkitys ja hoitotulokset puuttuvat aineistosta. Potilaan sairauden todennäköisyyttä ei voida validoida näistä tiedostoista.')}</p></div>`)+card(t('Sample history · newest first','Näytehistoria · uusin ensin'),cultures.map((c,index)=>{const ii=isolates.filter(i=>i.culture_id===c.culture_id),st=tests.filter(s=>s.culture_id===c.culture_id);return `<details class="record" ${index===0?'open':''}><summary>${c.sample_date} · ${esc(value(c.specimen,'specimen'))} <span class="record-label">${esc(value(c.result,'result'))} · ${esc(lang==='fi'?c.ward_fi:c.ward_en)} · ${c.culture_id}</span></summary><div class="pad"><h3>${t('Sample details','Näytteen tiedot')}</h3>${dataTable([c])}<h3>${t('Organisms & growth','Mikrobit ja kasvu')}</h3>${dataTable(ii)}${ii.map(i=>`<p class="sub">${esc(i.organism)} · ${esc(i.quantity||t('Not quantified','Ei määrällistä tulosta'))} · ${esc(conditionContext(c.specimen))}</p>${['Escherichia coli','Staphylococcus aureus'].includes(i.organism)?`<button class="open-reference" data-image="${i.organism==='Escherichia coli'?'ecoli':'saureus'}">${t('View reference microscopy','Katso mikroskopian viitekuva')} ↗</button>`:''}`).join('')}<h3>${t('Antibiotic tests','Antibioottitestit')}</h3>${dataTable(st)}</div></details>`;}).join('')):'<div class="empty">'+t('Patient not found. Try P000001 or use a Patient ID from Laboratory data.','Potilasta ei löytynyt. Kokeile P000001 tai käytä Laboratoriotiedot-näkymän potilastunnusta.')+'</div>');$('#patient-form').onsubmit=e=>{e.preventDefault();pid=$('#pid').value.trim().toUpperCase();render();};if(p)$('#patient-download').onclick=()=>saveBlob(pid+'.json',JSON.stringify({patient:p,cultures,isolates,susceptibility:tests},null,2),'application/json');$$('.open-reference').forEach(b=>b.onclick=()=>{imageName=b.dataset.image;go('images');});bindPatientLinks();}
function conditionContext(specimen){return specimen==='urine'?t('Urine: infection and asymptomatic carriage cannot be distinguished without clinical information.','Virtsa: infektiota ja oireetonta kantajuutta ei voi erottaa ilman kliinisiä tietoja.'):specimen==='wound'?t('Wound: growth may reflect colonisation or infection; the grade is not a diagnosis.','Haava: kasvu voi olla kolonisaatiota tai infektiota; kasvuluokka ei ole diagnoosi.'):t('Blood: clinical review is needed; sepsis cannot be predicted from these records.','Veri: tarvitaan kliininen arvio; sepsistä ei voida ennustaa näistä tiedoista.');}
function growth(){const rows=report.recent,groups=['10^3','10^4','>=10^5','+','++','+++',''].filter(q=>rows.some(r=>(r[12]||'')===q));const rowsOut=groups.map(q=>({quantity:q||'not_reported',count:rows.filter(r=>(r[12]||'')===q).length,eligible:rows.length,share_pct:rows.length>=30?100*rows.filter(r=>(r[12]||'')===q).length/rows.length:''}));const band=q=>['>=10^5','+++'].includes(q)?['red',t('Higher growth','Runsaampi kasvu')]:['10^4','++'].includes(q)?['amber',t('Intermediate growth','Kohtalainen kasvu')]:['10^3','+'].includes(q)?['green',t('Lower growth','Vähäisempi kasvu')]:['',t('Not quantified','Ei määrällistä tulosta')];$('#content').innerHTML=notice(t('Growth amount is not a percentage. The percentages below show the share of first isolates in each recorded growth category. Red, yellow and green indicate higher, intermediate and lower recorded growth—not a validated risk or safety score.','Kasvun määrä ei ole prosentti. Alla prosentti kuvaa ensisolaattien osuutta kussakin kirjatussa kasvuluokassa. Punainen, keltainen ja vihreä tarkoittavat runsaampaa, kohtalaista ja vähäisempää kasvua – eivät validoitua riski- tai turvallisuusarviota.'),true)+`<div class="grid">${card(t('Growth distribution · previous four weeks','Kasvun jakauma · edelliset neljä viikkoa'),`<div class="table-wrap"><table><thead><tr><th>${t('Growth amount','Kasvun määrä')}</th><th>${t('Display band','Näyttöluokka')}</th><th>n</th><th>${t('Share','Osuus')}</th></tr></thead><tbody>${rowsOut.map(g=>`<tr><td><b>${esc(g.quantity==='not_reported'?t('Not reported','Ei raportoitu'):g.quantity)}</b><small>${g.quantity.includes('10')?'CFU/mL':g.quantity==='not_reported'?'':t('Ordinal wound grade','Haavan järjestysasteikko')}</small></td><td><span class="tag ${band(g.quantity)[0]}">${band(g.quantity)[1]}</span></td><td>${g.count}</td><td>${g.share_pct===''?t('Withheld · n < 30','Ei raportoida · n < 30'):percent(g.share_pct/100)}</td></tr>`).join('')||'<tr><td colspan="4">'+t('No findings','Ei löydöksiä')+'</td></tr>'}</tbody></table></div><div class="table-foot">${t('Denominator','Nimittäjä')}: ${rows.length} ${t('eligible first isolates','kelpoista ensisolaattia')}. <button id="growth-export">↓ CSV</button></div>`)}${card(t('Resistance markers','Resistenssimerkit'),`<div class="pad">${[['ESBL',9],['MRSA',10],['VRE',13],['CPE',14]].map(([k,index])=>{const count=rows.filter(r=>r[index]===1).length;return `<div class="toolbar" style="margin-bottom:14px"><b>${k}</b><span>${count} / ${rows.length}</span><span class="tag">${rows.length>=30?percent(count/rows.length):t('Below minimum','Alle vähimmäismäärän')}</span></div>`;}).join('')}<p class="sub">${t('Shares use all first isolates in the selected cohort, not species-specific national denominators. Positive flags are reported phenotypes, not disease predictions.','Osuudet lasketaan valitun ryhmän kaikista ensisolaateista, eivät lajikohtaisista kansallisista nimittäjistä. Positiiviset merkinnät ovat kirjattuja ilmiasuja, eivät sairausennusteita.')}</p></div>`)}</div>`+card(t('Thresholds and interpretation','Rajat ja tulkinta'),`<div class="pad"><div class="grid equal"><div><h3>${t('Urine · CFU/mL','Virtsa · CFU/mL')}</h3><p><span class="tag green">10³ = 1,000</span> <span class="tag amber">10⁴ = 10,000</span> <span class="tag red">≥10⁵ ≥100,000</span></p><p>${t('These are the exact categories in the supplied file. The upper category is a lower bound. They are display thresholds, not universal diagnostic thresholds. Lower urine counts can still be significant in symptomatic patients; high counts may occur without symptomatic infection.','Nämä ovat tiedoston täsmälliset luokat. Ylin luokka on alaraja. Ne ovat näyttörajoja, eivät yleispäteviä diagnostisia rajoja. Vähäisetkin virtsan bakteerimäärät voivat olla merkittäviä oireisella potilaalla, ja suuria määriä voi esiintyä ilman oireista infektiota.')}</p></div><div><h3>${t('Wound & blood','Haava ja veri')}</h3><p>${t('Wound + / ++ / +++ is an ordinal laboratory grade. There is no valid conversion to CFU/mL or bacterial percentage in the README. Blood findings have no quantity value.','Haavan + / ++ / +++ on laboratorion järjestysasteikko. README ei anna pätevää muunnosta CFU/mL-arvoksi tai bakteeriprosentiksi. Verilöydöksillä ei ole määrätietoa.')}</p><p>${t('Admission day 3 or later is a surveillance timing proxy (at least two calendar days after admission), not confirmation of hospital acquisition.','Hoitopäivä 3 tai myöhemmin on seurannan ajoitusmuuttuja (vähintään kaksi kalenteripäivää sisäänotosta), ei vahvistus sairaalaperäisyydestä.')}</p></div></div><p class="source-note">${t('Interpretation sources','Tulkintalähteet')}: <a href="https://www.gov.uk/government/publications/urinary-tract-infection-diagnosis/diagnosis-of-urinary-tract-infections-quick-reference-tools-for-primary-care" target="_blank" rel="noopener">UKHSA</a> · <a href="https://www.idsociety.org/practice-guideline/asymptomatic-bacteriuria/" target="_blank" rel="noopener">IDSA 2019</a></p></div>`);$('#growth-export').onclick=()=>csv('MicrobeLog-growth',rowsOut);}
const imageRefs={ecoli:{name:'Escherichia coli',id:12166,credit:'CDC / Charles Farmer (1965)',file:'images/ecoli.jpg',caption:['Fluorescent-antibody-stained fecal smear. Not a urinary sample.','Fluoresoivalla vasta-aineella värjätty ulostenäyte. Ei virtsanäyte.']},saureus:{name:'Staphylococcus aureus',id:2296,credit:'CDC / Dr. Richard Facklam (1980)',file:'images/saureus.jpg',caption:['Photomicrograph; source magnification 250×.','Valomikroskooppikuva; lähteen suurennos 250×.']}};
function images(){const ref=imageRefs[imageName];$('#content').innerHTML=notice(t('Public-domain teaching references, associated by species only. These are not images of the synthetic patients. Image measurements cannot establish CFU/mL, susceptibility or disease.','Julkisia opetuksen viitekuvia, jotka on yhdistetty vain lajin perusteella. Nämä eivät ole synteettisten potilaiden kuvia. Kuvamittauksista ei voi päätellä CFU/mL-arvoa, herkkyyttä tai sairautta.'))+card(t('Microscopy workspace','Mikroskopian työtila'),`<div class="pad toolbar"><label>${t('Reference sample','Viitenäyte')} <select id="image-select">${Object.entries(imageRefs).map(([k,v])=>`<option value="${k}" ${k===imageName?'selected':''}>${v.name}</option>`).join('')}</select></label><label>${t('Open your own image','Avaa oma kuva')} <input type="file" id="image-upload" accept="image/png,image/jpeg,image/webp"></label><button id="download-image">↓ PNG</button><button id="image-dataset">${t('Matching laboratory findings','Vastaavat laboratoriolöydökset')} →</button></div><div class="image-layout"><div><div class="canvas-wrap"><canvas id="microscope" aria-label="${t('Microscopy image preview','Mikroskooppikuvan esikatselu')}"></canvas></div><div class="pad sub" id="image-credit">${esc(ref.name)} · ${ref.credit} · ${t(...ref.caption)}<br>${t('Public domain','Vapaa käyttö')} · <a href="https://wwwn.cdc.gov/phil/Details.aspx?pid=${ref.id}" target="_blank" rel="noopener">CDC PHIL ${ref.id}</a> · ${t('No calibrated pixel scale supplied','Kalibroitua pikseliasteikkoa ei ole')}</div><div class="pad" id="image-measurements"></div></div><div class="pad"><h3>${t('Quick inspection','Pikatarkastelu')}</h3><label class="slider">${t('Brightness','Kirkkaus')}<input id="brightness" type="range" min="-100" max="100" value="0"></label><label class="slider">${t('Contrast','Kontrasti')}<input id="contrast" type="range" min="-100" max="100" value="0"></label><label><input id="grayscale" type="checkbox"> ${t('Grayscale','Harmaasävy')}</label><br><label><input id="invert" type="checkbox"> ${t('Invert','Käänteiset värit')}</label><br><label><input id="threshold-on" type="checkbox"> ${t('Binary threshold','Binäärinen kynnystys')}</label><label class="slider">${t('Threshold · 0–255','Kynnysarvo · 0–255')}<input id="threshold" type="range" min="0" max="255" value="128"></label><label class="field">${t('Minimum object size · pixels','Kohteen vähimmäiskoko · pikseliä')}<input id="min-size" type="number" min="1" value="10"></label><div class="image-tools"><button id="measure">${t('Measure objects','Mittaa kohteet')}</button><button id="reset-image">${t('Reset','Palauta')}</button><button id="export-objects">↓ CSV</button></div><p class="sub">${t('Measurements use connected bright regions in the thresholded image. Regions are not validated bacterial counts. Areas are pixels, not physical units.','Mittaukset käyttävät kynnystetyn kuvan yhtenäisiä vaaleita alueita. Alueet eivät ole validoituja bakteerimääriä. Pinta-alat ovat pikseleinä, eivät fyysisinä yksikköinä.')}</p></div></div>`)+card(t('Full ImageJ · within MicrobeLog','ImageJ kokonaisuudessaan · MicrobeLogin sisällä'),`<div class="pad"><p>${t('Launch ImageJ.JS for filters, thresholding, measurements, particle analysis and macros. It downloads a third-party runtime and may take a moment. The public reference image opens through its CDC URL. For a local image, use ImageJ File → Open.','Käynnistä ImageJ.JS suodattimia, kynnystystä, mittauksia, hiukkasanalyysia ja makroja varten. Ulkopuolisen suoritusympäristön lataaminen voi kestää hetken. Julkinen viitekuva avautuu CDC-osoitteesta. Avaa paikallinen kuva ImageJ:n File → Open -valikosta.')}</p><div class="frame-actions"><button class="primary" id="launch-imagej">${t('Start embedded ImageJ','Käynnistä upotettu ImageJ')}</button><a id="imagej-external" href="https://ij.imjoy.io/?open=${encodeURIComponent('https://wwwn.cdc.gov/phil/PHIL_Images/'+ref.id+'/'+ref.id+'_lores.jpg')}" target="_blank" rel="noopener">${t('Open in a separate window','Avaa erillisessä ikkunassa')} ↗</a><a href="review-image.ijm" download>${t('Review macro','Tarkistusmakro')} ↓</a></div></div><div id="imagej-host"></div>`);$('#image-select').onchange=e=>{imageName=e.target.value;render();};$('#image-dataset').onclick=()=>{tableName='isolates';searchField='organism';search=ref.name;page=0;go('explorer');};const load=src=>{const img=new Image();img.onload=()=>{if(view!=='images'||!$('#microscope'))return;const c=$('#microscope');c.width=img.width;c.height=img.height;c.getContext('2d').drawImage(img,0,0);imageOriginal=c.getContext('2d').getImageData(0,0,c.width,c.height);objectStats=[];updateImage();};img.onerror=()=>toast(t('Image could not be opened.','Kuvaa ei voitu avata.'));img.src=src;};load(ref.file);$('#image-upload').onchange=e=>{const file=e.target.files[0];if(!file)return;const url=URL.createObjectURL(file);load(url);$('#image-credit').textContent=t('Local image · stays in this browser. Not linked to a patient.','Paikallinen kuva · säilyy tässä selaimessa. Ei yhdistetty potilaaseen.');};['brightness','contrast','grayscale','invert','threshold','threshold-on'].forEach(k=>$('#'+k).oninput=updateImage);$('#reset-image').onclick=()=>{['brightness','contrast'].forEach(k=>$('#'+k).value=0);['grayscale','invert','threshold-on'].forEach(k=>$('#'+k).checked=false);updateImage();};$('#download-image').onclick=()=>{const a=document.createElement('a');a.href=$('#microscope').toDataURL('image/png');a.download='MicrobeLog-review.png';a.click();};$('#measure').onclick=measureObjects;$('#export-objects').onclick=()=>csv('MicrobeLog-image-objects',objectStats);$('#launch-imagej').onclick=()=>{$('#imagej-host').innerHTML=`<iframe class="tool-frame" title="ImageJ.JS microscopy analysis" src="${$('#imagej-external').href}" allow="clipboard-read; clipboard-write; fullscreen" allowfullscreen></iframe>`;toast(t('ImageJ runtime is loading. Use the separate window if embedding is blocked.','ImageJ latautuu. Käytä erillistä ikkunaa, jos upotus on estetty.'));};}
function updateImage(){if(!imageOriginal||!$('#microscope'))return;const canvas=$('#microscope'),ctx=canvas.getContext('2d'),copy=new ImageData(new Uint8ClampedArray(imageOriginal.data),imageOriginal.width,imageOriginal.height),brightness=+$('#brightness').value,contrast=+$('#contrast').value,factor=(259*(contrast+255))/(255*(259-contrast));for(let i=0;i<copy.data.length;i+=4){let c=[0,1,2].map(k=>Math.max(0,Math.min(255,factor*(copy.data[i+k]-128)+128+brightness)));const gray=.299*c[0]+.587*c[1]+.114*c[2];if($('#threshold-on').checked)c=c.map(()=>gray>=+$('#threshold').value?255:0);else if($('#grayscale').checked)c=c.map(()=>gray);if($('#invert').checked)c=c.map(v=>255-v);for(let k=0;k<3;k++)copy.data[i+k]=c[k];}ctx.putImageData(copy,0,0);objectStats=[];$('#image-measurements').textContent=t('Adjust the image, then measure thresholded regions.','Säädä kuvaa ja mittaa sitten kynnystetyt alueet.');}
function connectedObjects(pixels,w,h,minSize){const seen=new Uint8Array(w*h),out=[],stack=new Int32Array(w*h);for(let start=0;start<w*h;start++){if(seen[start]||pixels[start*4]!==255)continue;let count=0,sx=0,sy=0,top=1;stack[0]=start;seen[start]=1;while(top){const p=stack[--top],x=p%w,y=Math.floor(p/w);count++;sx+=x;sy+=y;const adjacent=[];if(x>0)adjacent.push(p-1);if(x<w-1)adjacent.push(p+1);if(y>0)adjacent.push(p-w);if(y<h-1)adjacent.push(p+w);for(const q of adjacent)if(!seen[q]&&pixels[q*4]===255){seen[q]=1;stack[top++]=q;}}if(count>=minSize)out.push({object_id:out.length+1,area_pixels:count,centroid_x:sx/count,centroid_y:sy/count});}return out;}
function measureObjects(){if(!$('#threshold-on').checked)return toast(t('Enable binary threshold before measuring.','Ota binäärinen kynnystys käyttöön ennen mittausta.'));const c=$('#microscope'),p=c.getContext('2d').getImageData(0,0,c.width,c.height);objectStats=connectedObjects(p.data,c.width,c.height,Math.max(1,+$('#min-size').value||1));$('#image-measurements').innerHTML=`<b>${objectStats.length} ${t('segmented regions','segmentoitua aluetta')}</b><p class="sub">${t('4-connected white regions; uncalibrated pixel measurements, not bacterial counts. CSV includes every detected region.','4-yhteyksiset valkoiset alueet; kalibroimattomat pikselimittaukset, eivät bakteerimääriä. CSV sisältää jokaisen havaitun alueen.')}</p>${dataTable(objectStats,20)}`;}
let webR=null,aiEnabled=false;
async function research(){const script=await fetch('analysis.R').then(r=>r.text());if(view!=='research')return;$('#content').innerHTML=card(t('Download and reproduce','Lataa ja toista analyysi'),`<div class="pad"><p>${t('Export the current report as a tidy statistics table, or download complete source tables for independent analysis. CSVs use UTF-8, comma separators and ISO dates. Suppressed percentages are blank in the export.','Vie nykyinen raportti yhtenäisenä tilastotauluna tai lataa täydet lähdetaulut omaa analyysiä varten. CSV-tiedostoissa on UTF-8-merkistö, pilkkuerotin ja ISO-päivämäärät. Raportoimatta jätetyt prosentit ovat viennissä tyhjiä.')}</p><div class="toolbar"><button class="primary" id="research-export">↓ ${t('Current report statistics','Nykyisen raportin tilastot')}</button><a href="analysis.R" download>↓ ${t('Reproducible R script','Toistettava R-skripti')}</a><a href="datasets/README.md" download>↓ ${t('Dataset documentation','Aineiston dokumentaatio')}</a></div><hr><div class="toolbar">${Object.entries(tableLabels).map(([k,l])=>`<a href="datasets/${k}.csv" download>${t(...l)} ↓</a>`).join(' · ')}</div></div>`)+card(t('R notebook · run in this dashboard','R-muistikirja · suorita tässä näkymässä'),`<div class="pad"><p>${t('Start webR to run real R code locally in your browser. The current report is available as a data frame named stats. No API key is needed. First launch downloads the R runtime.','Käynnistä webR suorittaaksesi oikeaa R-koodia paikallisesti selaimessa. Nykyinen raportti on saatavilla stats-nimisessä taulussa. API-avainta ei tarvita. Ensimmäinen käynnistys lataa R-ympäristön.')}</p><textarea class="code" id="r-code" aria-label="R code"># MicrobeLog: verified report aggregates\nprint(stats)\nsummary(stats)\n# Edit this code to analyse the selected report.</textarea><div class="toolbar" style="margin-top:12px"><button class="primary" id="run-r">▶ ${t('Run R','Suorita R')}</button><a href="https://webr.r-wasm.org/latest/" target="_blank" rel="noopener">${t('Full R console','Täysi R-konsoli')} ↗</a></div><p class="source-note">${t('Browser memory and network limits apply. This notebook receives aggregate counts, not patient records.','Selaimen muisti- ja verkkorajoitukset ovat voimassa. Muistikirja saa koontilukuja, ei potilastietoja.')}</p></div><pre class="console" id="r-output">${t('R is not started.','R-ympäristöä ei ole käynnistetty.')}</pre>`)+card(t('Independent analysis script','Itsenäinen analyysiskripti'),`<div class="pad"><p>${t('For analysis from raw records, put the downloaded CSVs and analysis.R in the same folder. Edit ward, organism and sample filters at the top. It independently selects first isolates and withholds rates below 30 tests.','Raakatietojen analyysiä varten laita ladatut CSV-tiedostot ja analysis.R samaan kansioon. Muokkaa osasto-, mikrobi- ja näytesuodattimia skriptin alussa. Skripti valitsee itsenäisesti ensisolaatit ja jättää prosentit raportoimatta alle 30 tutkimuksella.')}</p><details><summary>${t('View R source','Katso R-lähdekoodi')}</summary><pre style="overflow:auto;font-size:11px">${esc(script)}</pre></details></div>`);$('#research-export').onclick=exportReport;$('#run-r').onclick=runR;}
async function runR(){const button=$('#run-r'),output=$('#r-output');button.disabled=true;output.textContent=t('Starting R…','Käynnistetään R…');try{if(!webR){const mod=await import('https://webr.r-wasm.org/v0.5.4/webr.mjs');webR=new mod.WebR({channelType:mod.ChannelType.PostMessage});await webR.init();}const metrics=report.metrics,vector=(key)=>'c('+metrics.map(a=>a[key]).join(',')+')';await webR.evalRVoid(`stats <- data.frame(antibiotic=c(${metrics.map(a=>JSON.stringify(a.antibiotic_code)).join(',')}), n=c(${metrics.map(a=>a.now.n).join(',')}), R=c(${metrics.map(a=>a.now.r).join(',')}), S=c(${metrics.map(a=>a.now.s).join(',')}), resistance_pct=c(${metrics.map(a=>a.now.n>=30?100*a.now.rate:'NA_real_').join(',')}))`);const code=$('#r-code').value;const result=await webR.evalRString('paste(capture.output({'+code+'\n}), collapse="\\n")');output.textContent=result||t('Completed with no printed output.','Valmis, ei tulostetta.');}catch(e){output.textContent=t('R could not run: ','R-koodia ei voitu suorittaa: ')+e.message+'\n'+t('You can download the script or use the full R console.','Voit ladata skriptin tai käyttää täyttä R-konsolia.');webR=null;}finally{button.disabled=false;}}
function chat(){const welcome=t('Ask about resistance, compare women and men, find a patient record, or search a location. Answers are calculated from the synthetic dataset.','Kysy resistenssistä, vertaa naisia ja miehiä, etsi potilastietoja tai hae hoitopaikkaa. Vastaukset lasketaan synteettisestä aineistosta.');$('#content').innerHTML=notice(aiEnabled?t('AI-assisted query interpretation · answers are calculated locally from verified records.','Tekoälyavusteinen haun tulkinta · vastaukset lasketaan paikallisesti tarkistetuista tiedoista.'):t('Local bilingual data assistant · no external AI model is connected. It supports the examples below and reports the parsed filters. It cannot diagnose or recommend treatment.','Paikallinen kaksikielinen tietoavustaja · ulkoista tekoälymallia ei ole yhdistetty. Avustaja tukee alla olevia esimerkkejä ja näyttää tulkitut suodattimet. Se ei diagnosoi tai suosittele hoitoa.'))+`<div class="grid"><div>${card(t('Ask MicrobeLog','Kysy MicrobeLogilta'),`<div class="chat-messages" id="messages"><div class="message">${welcome}</div>${chatHistory.map(m=>`<div class="message ${m.role==='user'?'user':''}">${esc(m.text)}${m.source?`<small>${esc(m.source)}</small>`:''}</div>`).join('')}</div><div class="chips">${[t('Ampicillin resistance in E. coli urine','E. colin ampisilliiniresistenssi virtsassa'),t('Compare women and men','Vertaa naisia ja miehiä'),t('Show patient P000001','Näytä potilas P000001'),t('Explain S and R','Selitä S ja R')].map(q=>`<button class="suggestion" data-question="${esc(q)}">${q}</button>`).join('')}</div><form class="chat-form" id="chat-form"><input id="question" maxlength="500" required placeholder="${t('Ask in English or Finnish…','Kysy englanniksi tai suomeksi…')}" aria-label="${t('Your question','Kysymyksesi')}"><button class="primary">${t('Ask','Kysy')} ↑</button></form>`)}${pendingPatient?`<button id="open-chat-patient">${t('Open patient record','Avaa potilastiedot')} ${pendingPatient} →</button>`:''}</div><div>${card(t('Search examples','Hakuesimerkkejä'),`<div class="pad"><p>“${t('Annual ciprofloxacin resistance in E. coli urine in women','Naisten virtsan E. colin siprofloksasiiniresistenssi vuodessa')}”</p><p>“${t('MRSA in ICU','MRSA teho-osastolla')}”</p><p>“${t('What does high bacterial growth mean?','Mitä runsas bakteerikasvu tarkoittaa?')}”</p><p class="sub">${t('Supported: organisms, antibiotic names or codes, location names or codes, urine/blood/wound, women/men and annual/four-week periods. Unrecognised requests return help rather than invented answers.','Tuetut haut: mikrobit, antibioottien nimet tai koodit, hoitopaikkojen nimet tai koodit, virtsa/veri/haava, naiset/miehet ja vuosi/neljä viikkoa. Tunnistamattomiin pyyntöihin annetaan ohjeita keksittyjen vastausten sijaan.')}</p></div>`)}</div></div>`;$('#chat-form').onsubmit=e=>{e.preventDefault();askQuestion($('#question').value);};$$('.suggestion').forEach(b=>b.onclick=()=>askQuestion(b.dataset.question));if(pendingPatient)$('#open-chat-patient').onclick=()=>{pid=pendingPatient;go('patients');};$('#messages').scrollTop=$('#messages').scrollHeight;}
async function askQuestion(question){if(!question.trim())return;chatHistory.push({role:'user',text:question});let canonical=question;if(aiEnabled){try{const r=await fetch('/api/ai/interpret',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question})});if(r.ok){const interpreted=await r.json();if(typeof interpreted.canonical_query==='string')canonical=interpreted.canonical_query;}}catch(e){toast(t('AI unavailable; using local search.','Tekoäly ei ole saatavilla; käytetään paikallishakua.'));}}const q=canonical.toLowerCase(),parsed={...f},annual=/annual|year|vuos|vuode/.test(q);parsed.date=data.meta.end;pendingPatient=null;let answer='',source='';const patient=q.match(/p\d{6}/i);if(patient){const [ps,cs]=await Promise.all([raw('patients'),raw('cultures')]);pendingPatient=patient[0].toUpperCase();const p=ps.find(p=>p.patient_id===pendingPatient),cc=cs.filter(c=>c.patient_id===pendingPatient);answer=p?`${pendingPatient} · ${value(p.sex,'sex')} · ${t('Birth year','Syntymävuosi')} ${p.birth_year} · ${p.home_area}\n${cc.length} ${t('culture samples. Open the linked record below to see all findings and test results.','viljelynäytettä. Avaa tiedot alta nähdäksesi kaikki löydökset ja tutkimustulokset.')}`:t('No patient matches that ID.','Tunnusta vastaavaa potilasta ei löytynyt.');source='patients → cultures';}else if(/diagnos|disease|condition|predict|sairau|ennust|sepsis|treat|hoito|lääkitys/.test(q)){answer=t('These records cannot predict a disease or choose treatment. They do not contain symptoms, diagnoses, medication or outcomes. I can show culture findings, antibiotic test results and surveillance changes instead.','Näistä tiedoista ei voi ennustaa sairautta tai valita hoitoa. Oireet, diagnoosit, lääkitys ja hoitotulokset puuttuvat. Voin näyttää viljelylöydöksiä, herkkyystuloksia ja seurannan muutoksia.');}else if(/explain|selitä|means|tarkoitta/.test(q)&&/\bs\b|\br\b|suscept|herkk/.test(q)){answer=t('S = susceptible; R = resistant. Resistance percentage = R / (R + S) × 100. Only the first isolate per patient, species, sample type and period is counted. Rates require at least 30 tested isolates per antibiotic. Missing results are excluded.','S = herkkä; R = resistentti. Resistenssiprosentti = R / (R + S) × 100. Mukaan lasketaan vain ensimmäinen isolaatti potilasta, lajia, näytetyyppiä ja jaksoa kohti. Osuus vaatii vähintään 30 tutkittua isolaattia antibioottia kohden. Puuttuvat tulokset jätetään pois.');source='Dataset README · susceptibility.result';}else if(/quant|growth|bacteri|kasvu|määrä/.test(q)&&!/resistan|resisten/.test(q)){answer=t('Urine quantities are 10³, 10⁴ or ≥10⁵ CFU/mL. Wound grades are +, ++ or +++. Blood quantities are blank. These are not percentages or universal safety thresholds. Lower urine counts can be significant in symptomatic people; high counts alone do not prove infection. See Bacterial growth for category shares.','Virtsan määrät ovat 10³, 10⁴ tai ≥10⁵ CFU/mL. Haavan luokat ovat +, ++ tai +++. Verinäytteiden määrä on tyhjä. Nämä eivät ole prosentteja tai yleispäteviä turvallisuusrajoja. Vähäiset määrät voivat olla merkittäviä oireisella; runsas kasvu ei yksin vahvista infektiota. Katso luokkien osuudet Bakteerikasvu-näkymästä.');source='Dataset README · UKHSA · IDSA';}else{if(/mrsa/.test(q)){parsed.organism=String(data.organisms.indexOf('Staphylococcus aureus'));parsed.specimen='ALL';}let recognised=/resist|suscept|herkk|compare|vertaa|mrsa|esbl|vre|cpe|test|tulos/.test(q);for(let i=0;i<data.organisms.length;i++){const o=data.organisms[i];if(q.includes(o.toLowerCase())||(o==='Escherichia coli'&&/e\.?\s*coli|e\. colin/.test(q))){parsed.organism=String(i);recognised=true;}}for(const w of data.wards){if(q.includes(w.ward_en.toLowerCase())||q.includes(w.ward_fi.toLowerCase())||new RegExp('\\b'+w.ward_code.toLowerCase()+'\\b').test(q)){parsed.ward=w.ward_code;recognised=true;}}for(const [regex,v]of [[/urine|virtsa/,'urine'],[/blood|veri|verestä/,'blood'],[/wound|haava/,'wound']])if(regex.test(q)){parsed.specimen=v;recognised=true;}if(/all wards|kaikki osast|kaikilla osast/.test(q))parsed.ward='ALL';if(/women|female|naise|naist/.test(q))parsed.sex='F';if(/men\b|male|mieh|miest/.test(q)&&!/women/.test(q))parsed.sex='M';const ab=data.antibiotics.find(a=>q.includes(a.antibiotic.toLowerCase())||q.includes(a.antibiotic_fi.toLowerCase())||new RegExp('\\b'+a.antibiotic_code.toLowerCase()+'\\b').test(q))||data.antibiotics.find(a=>a.antibiotic_code==='AMP');if(/compare|vertaa/.test(q)){parsed.organism=String(data.organisms.indexOf('Escherichia coli'));parsed.specimen='urine';answer=['F','M'].map(sex=>{const c=AEI.counts(AEI.cohort(data,{...parsed,sex},AEI.shift(parsed.date,annual?-364:-27),parsed.date),ab.antibiotic_code);return value(sex,'sex')+': '+(c.n>=30?percent(c.rate)+' R':t('rate withheld','osuutta ei raportoida'))+` · R ${c.r} / n ${c.n}`;}).join('\n');}else if(recognised){const computed=AEI.compute(data,parsed),m=computed.metrics.find(a=>a.antibiotic_code===ab.antibiotic_code);if(/mrsa|esbl|vre|cpe/.test(q)&&!q.includes(ab.antibiotic_code.toLowerCase())){const k=q.match(/mrsa|esbl|vre|cpe/)[0],idx={esbl:9,mrsa:10,vre:13,cpe:14}[k],rows=annual?computed.annual:computed.recent,count=rows.filter(r=>r[idx]===1).length;answer=`${k.toUpperCase()}: ${count} / ${rows.length} · ${rows.length>=30?percent(count/rows.length):t('rate withheld below 30','osuutta ei raportoida alle 30 löydöksellä')}`;}else if(m){const c=annual?m.year:m.now;answer=`${lang==='fi'?m.antibiotic_fi:m.antibiotic}\n${c.n>=30?percent(c.rate)+' '+t('resistant','resistenttejä')+' · '+percent(1-c.rate)+' '+t('susceptible','herkkiä'):t('Percentage withheld: fewer than 30 tested first isolates.','Osuutta ei raportoida: alle 30 tutkittua ensisolaattia.')}\nR ${c.r} · S ${c.s} · n ${c.n}`;}else answer=t('No recorded tests match the parsed cohort. Missing tests are not treated as susceptible.','Tulkitulle ryhmälle ei ole kirjattuja tutkimuksia. Puuttuvia testejä ei käsitellä herkkinä.');}else answer=t('I could not map this request to a supported dataset question. Try an antibiotic, organism, location, patient ID, or one of the examples.','En pystynyt yhdistämään pyyntöä tuettuun aineistohakuun. Kokeile antibioottia, mikrobia, hoitopaikkaa, potilastunnusta tai esimerkkiä.');if(recognised){source=`${t('Parsed scope','Tulkittu rajaus')}: ${parsed.ward} · ${parsed.organism==='ALL'?'ALL':data.organisms[+parsed.organism]} · ${parsed.specimen} · ${annual?'365':'28'} d · ${parsed.date}. ${t('Other active report filters retained. First-isolate rule applied.','Muut raportin suodattimet säilyvät. Ensisolaattisääntö käytössä.')}`;}}chatHistory.push({role:'assistant',text:answer,source});if(view==='chat')chat();}
function methods(){$('#content').innerHTML=`<div class="grid"><div>${card(t('How MicrobeLog calculates rates','Näin MicrobeLog laskee osuudet'),`<div class="pad method-steps">${[[t('Link the laboratory records','Yhdistä laboratoriotiedot'),t('Patient → culture sample → organism finding → antibiotic result, using patient_id, culture_id and isolate_id. All six source tables remain browsable.','Potilas → viljelynäyte → mikrobilöydös → herkkyystulos. Avaimet ovat patient_id, culture_id ja isolate_id. Kaikkia kuutta lähdetaulua voi selata.')],[t('Choose the cohort and reporting date','Valitse ryhmä ja raportointipäivä'),t('Apply the location, organism, specimen and demographic filters. The recent period is 28 inclusive calendar days; the annual period is 365 inclusive days ending on the selected date.','Käytä hoitopaikka-, mikrobi-, näyte- ja väestösuodattimia. Lyhyt jakso on 28 kalenteripäivää ja vuosijakso 365 päivää valittuun päivään asti, päätepäivät mukaan lukien.')],[t('Keep only the first isolate','Säilytä vain ensisolaatti'),t('Within each selected cohort and period, retain the earliest isolate per patient, species and specimen type. Ties use culture ID then isolate ID. Each period is deduplicated independently.','Kussakin valitussa ryhmässä ja jaksossa säilytetään aikaisin isolaatti potilasta, lajia ja näytetyyppiä kohti. Tasatilanteet ratkaistaan näyte- ja löydöstunnuksella. Jaksojen toistot poistetaan erikseen.')],[t('Count only recorded tests','Laske vain kirjatut testit'),t('Resistance = R / (R + S). Susceptibility = S / (R + S). Each antibiotic has its own tested-isolate denominator. No imputation of missing tests.','Resistenssi = R / (R + S). Herkkyys = S / (R + S). Jokaisella antibiootilla on oma tutkittujen isolaattien nimittäjä. Puuttuvia tuloksia ei täydennetä.')],[t('Apply the minimum sample rule','Käytä vähimmäisotosta'),t('Display percentages only at n ≥ 30. Keep the counts visible below that threshold. Evidence panels provide Wilson 95% confidence intervals for reportable rates.','Näytä osuudet vasta, kun n ≥ 30. Pidä lukumäärät näkyvillä rajan alapuolellakin. Tietopaneelit näyttävät raportoitaville osuuksille Wilsonin 95 % luottamusvälit.')],[t('Review changes and context','Tarkista muutokset ja asiayhteys'),t('Recent changes use a separate preceding-year baseline. Thresholds and adjusted tests are exploratory demo rules. The annual display overlaps the recent period; the signal baseline does not.','Viimeisimpiä muutoksia verrataan erilliseen edeltävään vuoteen. Rajat ja korjatut testit ovat demon alustavia sääntöjä. Vuosinäyttö sisältää lyhyen jakson, mutta signaalin vertailutaso ei.')]].map(([h,p])=>`<div class="method-step"><div><b>${h}</b><p>${p}</p></div></div>`).join('')}</div>`)}</div><div>${card(t('Dataset scope & limitations','Aineiston kattavuus ja rajoitukset'),`<div class="pad"><p>${num(data.meta.patients)} ${t('invented patients','keksittyä potilasta')} · ${num(data.meta.cultures)} ${t('cultures','viljelyä')} · ${num(data.meta.isolates)} ${t('isolates','isolaattia')} · ${num(data.meta.tests)} ${t('antibiotic results','herkkyystulosta')}.</p><p>${data.meta.start} – ${data.meta.end} · 9 ${t('care locations','hoitopaikkaa')}.</p><p>${t('Urinary/blood E. coli resistance and ESBL/MRSA shares are roughly calibrated to Finres 2023. Other rates are illustrative. Intrinsic patterns follow EUCAST Expected Resistant Phenotypes v1.2. This demo does not replace a current clinical breakpoint reference.','Virtsan ja veren E. colin resistenssi sekä ESBL/MRSA-osuudet on kalibroitu karkeasti Finres 2023 -tasolle. Muut osuudet ovat havainnollistavia. Luontaiset resistenssit noudattavat EUCAST Expected Resistant Phenotypes v1.2 -listaa. Demo ei korvaa ajantasaista kliinistä tulkintaohjetta.')}</p><p>${t('Only S/R: no I category, MIC or zone diameters. Urinary agents are reported for urine only. Latin species names are retained. No diagnoses, medication or clinical outcomes are present.','Vain S/R: ei I-luokkaa, MIC-arvoja tai estovyöhykkeitä. Virtsa-antibiootit raportoidaan vain virtsasta. Lajien latinankieliset nimet säilytetään. Diagnoosit, lääkitys ja hoitotulokset puuttuvat.')}</p><a href="datasets/README.md" download>${t('Read the original dataset README','Lue aineiston alkuperäinen README')} ↓</a></div>`)}${card(t('Updates & mobile use','Päivitykset ja mobiilikäyttö'),`<div class="pad"><p>${t('The app checks the hosted data file every 60 seconds while open and re-renders changed data. The supplied dataset is static; historical replay demonstrates incoming results. A real hospital connection and production identity controls are not implemented.','Sovellus tarkistaa julkaistun datatiedoston 60 sekunnin välein ollessaan avoinna ja päivittää muuttuneet tiedot. Toimitettu aineisto on staattinen; historiatoisto havainnollistaa saapuvia tuloksia. Varsinaista sairaalayhteyttä tai tuotannon tunnistautumista ei ole toteutettu.')}</p><p>${t('Installable web app for Android and iPhone/iPad. It uses mobile navigation and the same data as the desktop dashboard. This is not an App Store or Google Play binary.','Asennettava verkkosovellus Androidille sekä iPhonelle/iPadille. Mobiilinavigointi ja aineisto ovat samat kuin työpöytänäkymässä. Tämä ei ole App Store- tai Google Play -asennuspaketti.')}</p><button id="install-method">${t('Installation instructions','Asennusohjeet')}</button></div>`)}</div></div>`;$('#install-method').onclick=installHelp;}
function installHelp(){$('#modal').innerHTML=`<div class="dialog-head"><h2>${t('MicrobeLog on your phone','MicrobeLog puhelimessa')}</h2><button id="close">×</button></div><div class="pad"><img src="logo.svg" alt="MicrobeLog" style="width:220px"><h3>Android</h3><p>${t('Open MicrobeLog in Chrome. Use the browser menu → Add to Home screen → Install. If an install prompt is available, use the button below.','Avaa MicrobeLog Chromessa. Valitse selaimen valikosta Lisää aloitusnäyttöön → Asenna. Jos asennuskehote on saatavilla, käytä alla olevaa painiketta.')}</p><h3>iPhone / iPad</h3><p>${t('Open MicrobeLog in Safari. Tap Share → Add to Home Screen → Add. Open it from the new MicrobeLog icon.','Avaa MicrobeLog Safarissa. Napauta Jaa → Lisää Koti-valikkoon → Lisää. Avaa sovellus uudesta MicrobeLog-kuvakkeesta.')}</p><p class="sub">${t('Internet access and permission to view this private demo are required. No real patient login is implemented.','Tarvitset internetyhteyden ja oikeuden katsella tätä yksityistä demoa. Oikeaa potilaskirjautumista ei ole toteutettu.')}</p>${installEvent?`<button class="primary" id="install-now">${t('Install MicrobeLog','Asenna MicrobeLog')}</button>`:''}</div>`;$('#modal').showModal();$('#close').onclick=()=>$('#modal').close();if(installEvent)$('#install-now').onclick=async()=>{await installEvent.prompt();installEvent=null;$('#modal').close();};}
let datasetFingerprint='';
async function refreshData(manual=false){try{const r=await fetch('data.json',{cache:'no-store'});if(!r.ok)throw Error();const text=await r.text();if(text!==datasetFingerprint){const next=JSON.parse(text);datasetFingerprint=text;data=next;Object.keys(cache).forEach(k=>delete cache[k]);if(f.date>data.meta.end)f.date=data.meta.end;await render();}lastSync=t('Checked ','Tarkistettu ')+new Date().toLocaleTimeString(lang==='fi'?'fi-FI':'en-GB',{hour:'2-digit',minute:'2-digit'});if($('#sync'))$('#sync').textContent=lastSync;if(manual)toast(t('Data checked. Source ends on ','Tiedot tarkistettu. Aineisto päättyy ')+data.meta.end);}catch(e){if(manual)toast(t('Could not refresh. Existing data remains available.','Päivitys epäonnistui. Nykyiset tiedot ovat käytettävissä.'));}}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installEvent=e;});
async function init(){try{const r=await fetch('data.json');if(!r.ok)throw Error('Data unavailable');datasetFingerprint=await r.text();data=JSON.parse(datasetFingerprint);try{const status=await fetch('/api/ai/status').then(r=>r.ok?r.json():null);aiEnabled=!!status?.enabled;}catch(e){}f.organism=String(data.organisms.indexOf('Escherichia coli'));f.date=data.meta.end;document.documentElement.lang=lang;await render();setInterval(()=>{if(!document.hidden)refreshData();},60000);if('serviceWorker' in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});$('#modal').onclick=e=>{if(e.target===$('#modal'))$('#modal').close();};}catch(e){$('#app').innerHTML='<div class="boot">MicrobeLog<br><small>'+esc(t('Could not load the dataset. Please reload.','Aineiston lataus epäonnistui. Lataa sivu uudelleen.'))+'</small></div>';}}
init();
